-- =====================================================================
-- GLOWORA — seed data (generated from the app's built-in local data)
-- Run AFTER 01_schema_security_realtime.sql, in the Supabase SQL editor.
-- Safe to re-run: every insert is an upsert on the primary key.
--
-- Contains: 81 products, 9 categories, 27 subcategories, 5 brands,
--           4 badges, 9 customers, 50 orders, 4 reviews, 3 FAQs,
--           3 social links, 3 banners, 19 governorates, page copy, store settings, and 3 team accounts.
-- =====================================================================

-- governorates (19)
on conflict (id) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, enabled = excluded.enabled, delivery_price = excluded.delivery_price, position = excluded.position;

-- brands (5)
on conflict (id) do update set name = excluded.name, mark = excluded.mark, tone = excluded.tone, description = excluded.description, description_ar = excluded.description_ar, logo = excluded.logo, image = excluded.image, position = excluded.position;

-- categories (9)
on conflict (id) do update set name = excluded.name, name_ar = excluded.name_ar, image = excluded.image, position = excluded.position;

-- subcategories (27)
on conflict (category_id, id) do update set label = excluded.label, name = excluded.name, name_ar = excluded.name_ar, image = excluded.image, position = excluded.position;

-- badges (4)
on conflict (id) do update set label = excluded.label, label_ar = excluded.label_ar, tone = excluded.tone, position = excluded.position;

-- products (81)
on conflict (id) do update set name = excluded.name, name_ar = excluded.name_ar, subtitle = excluded.subtitle, subtitle_ar = excluded.subtitle_ar, sku = excluded.sku, brand_id = excluded.brand_id, category_id = excluded.category_id, subcategory_id = excluded.subcategory_id, price = excluded.price, discount_price = excluded.discount_price, description = excluded.description, description_ar = excluded.description_ar, stock = excluded.stock, images = excluded.images, status = excluded.status, badge = excluded.badge, badges = excluded.badges, sections = excluded.sections, rating = excluded.rating, reviews = excluded.reviews, benefits = excluded.benefits, created_at = excluded.created_at;

on conflict (id) do update set name = excluded.name, name_ar = excluded.name_ar, subtitle = excluded.subtitle, subtitle_ar = excluded.subtitle_ar, sku = excluded.sku, brand_id = excluded.brand_id, category_id = excluded.category_id, subcategory_id = excluded.subcategory_id, price = excluded.price, discount_price = excluded.discount_price, description = excluded.description, description_ar = excluded.description_ar, stock = excluded.stock, images = excluded.images, status = excluded.status, badge = excluded.badge, badges = excluded.badges, sections = excluded.sections, rating = excluded.rating, reviews = excluded.reviews, benefits = excluded.benefits, created_at = excluded.created_at;

-- customers (9)
on conflict (id) do update set name = excluded.name, email = excluded.email, phone = excluded.phone, city = excluded.city, registered_at = excluded.registered_at;

-- orders (50)
on conflict (id) do update set placed_at = excluded.placed_at, status = excluded.status, items = excluded.items, total = excluded.total, subtotal = excluded.subtotal, shipping = excluded.shipping, payment = excluded.payment, customer = excluded.customer, customer_id = excluded.customer_id, source = excluded.source, inventory_applied = excluded.inventory_applied, history = excluded.history;

-- reviews (4)
on conflict (id) do update set order_id = excluded.order_id, product_id = excluded.product_id, author = excluded.author, rating = excluded.rating, text = excluded.text, status = excluded.status, created_at = excluded.created_at;

-- faqs (3)
on conflict (id) do update set question = excluded.question, answer = excluded.answer, question_ar = excluded.question_ar, answer_ar = excluded.answer_ar, position = excluded.position;

-- socials (3)
on conflict (id) do update set label = excluded.label, href = excluded.href, position = excluded.position;

-- banners (3)
on conflict (id) do update set image = excluded.image, title = excluded.title, title_ar = excluded.title_ar, text = excluded.text, text_ar = excluded.text_ar, button = excluded.button, button_ar = excluded.button_ar, link = excluded.link, position = excluded.position;

-- cms_entries (20)
on conflict (key) do update set value = excluded.value;

-- store_settings (12)
on conflict (key) do update set value = excluded.value;

-- team accounts ------------------------------------------------------------
-- These are the demo logins shown on the admin sign-in screen. CHANGE THESE PASSWORDS
-- (Authentication → Users, or Settings → Change password in the admin) before going live.
-- If your project rejects direct inserts into auth.users, create the three users in the
-- dashboard instead (Authentication → Users → Add user) and run only the UPDATE below.
select '00000000-0000-0000-0000-000000000000', 'a0a0a0a0-0000-4000-8000-000000000001', 'authenticated', 'authenticated', 'admin@glowora.com', crypt('Glowora#Admin', gen_salt('bf')), now(),
       '{"provider":"email","providers":["email"]}'::jsonb, '{"name":"Lina Haddad"}'::jsonb, now(), now(), '', '', '', ''
where not exists (select 1 from auth.users where email = 'admin@glowora.com');
select gen_random_uuid(), u.id, u.id::text, jsonb_build_object('sub', u.id::text, 'email', u.email), 'email', now(), now(), now()
from auth.users u where u.email = 'admin@glowora.com'
  and not exists (select 1 from auth.identities i where i.user_id = u.id and i.provider = 'email');
select '00000000-0000-0000-0000-000000000000', 'a0a0a0a0-0000-4000-8000-000000000002', 'authenticated', 'authenticated', 'staff@glowora.com', crypt('Glowora#Staff', gen_salt('bf')), now(),
       '{"provider":"email","providers":["email"]}'::jsonb, '{"name":"Omar Nasser"}'::jsonb, now(), now(), '', '', '', ''
where not exists (select 1 from auth.users where email = 'staff@glowora.com');
select gen_random_uuid(), u.id, u.id::text, jsonb_build_object('sub', u.id::text, 'email', u.email), 'email', now(), now(), now()
from auth.users u where u.email = 'staff@glowora.com'
  and not exists (select 1 from auth.identities i where i.user_id = u.id and i.provider = 'email');
select '00000000-0000-0000-0000-000000000000', 'a0a0a0a0-0000-4000-8000-000000000003', 'authenticated', 'authenticated', 'maya@glowora.com', crypt('Glowora#Staff', gen_salt('bf')), now(),
       '{"provider":"email","providers":["email"]}'::jsonb, '{"name":"Maya Saleh"}'::jsonb, now(), now(), '', '', '', ''
where not exists (select 1 from auth.users where email = 'maya@glowora.com');
select gen_random_uuid(), u.id, u.id::text, jsonb_build_object('sub', u.id::text, 'email', u.email), 'email', now(), now(), now()
from auth.users u where u.email = 'maya@glowora.com'
  and not exists (select 1 from auth.identities i where i.user_id = u.id and i.provider = 'email');

update public.profiles set name = 'Lina Haddad', role = 'admin', active = true, permissions = '{"overview","orders","products","products.delete","categories","customers","team","settings","reviews","brands"}'::text[] where lower(email) = 'admin@glowora.com';
update public.profiles set name = 'Omar Nasser', role = 'staff', active = true, permissions = '{"overview","orders","products"}'::text[] where lower(email) = 'staff@glowora.com';
update public.profiles set name = 'Maya Saleh', role = 'staff', active = true, permissions = '{"overview","customers"}'::text[] where lower(email) = 'maya@glowora.com';
